/**
 * Parse --strategies from command-line arguments (comma-separated).
 * Also supports --strategy for backward compatibility (single strategy).
 * 
 * @returns {string[]|null} Array of strategy IDs or null if not provided
 */
function parseStrategiesArg() {
  const args = process.argv.slice(2);

  // Check for --strategies (plural, comma-separated)
  const strategiesIndex = args.indexOf("--strategies");
  if (strategiesIndex >= 0 && strategiesIndex < args.length - 1) {
    const strategiesStr = args[strategiesIndex + 1];
    return strategiesStr.split(",").map(s => s.trim()).filter(s => s.length > 0);
  }

  // Check for --strategy (singular, backward compatibility)
  const strategyIndex = args.indexOf("--strategy");
  if (strategyIndex >= 0 && strategyIndex < args.length - 1) {
    return [args[strategyIndex + 1].trim()];
  }

  return null;
}

