/**
 * Parse --settings or --settings-file from command-line arguments.
 * 
 * @returns {string|null} Path to settings file or null if not provided
 */
function parseSettingsFileArg() {
  const args = process.argv.slice(2);

  // Check for --settings
  const settingsIndex = args.indexOf("--settings");
  if (settingsIndex >= 0 && settingsIndex < args.length - 1) {
    return args[settingsIndex + 1].trim();
  }

  // Check for --settings-file (alias)
  const settingsFileIndex = args.indexOf("--settings-file");
  if (settingsFileIndex >= 0 && settingsFileIndex < args.length - 1) {
    return args[settingsFileIndex + 1].trim();
  }

  return null;
}

